//entertain.univie.ac.at/~hlavacs/index.php?item=showcase\", \"https://docs.univie.ac.at/people/supervisors/supervisors-computer-science\"], \"searched\": [\"\u4e2a\u4eba\u4e3b\u9875 showcase\uff08\u4ec5\u672c\u7855\u8bba\u6587\uff09\", \"u:theses\uff08\u7ad9\u70b9\u4e3a JS \u5e94\u7528\uff0c\u6309 web_search \u68c0\u7d22 Betreuer=Hlavacs\uff0c\u7ed3\u679c\u5747\u4e3a\u7855\u58eb\u8bba\u6587\uff09\", \"eprints.cs.univie.ac.at\", \"u:cris \u95e8\u6237\", \"LinkedIn \u5e16\u5b50\", \"Mathematics Genealogy\uff08\u67e5\u8be2\u672a\u8fd4\u56de\uff09\", \"DoCS alumni \u9875\uff08404\uff09\"]}, \"title_zh\": \"\u5927\u5b66\u6559\u6388\uff08Univ.-Prof.\uff09\uff1b\u6559\u80b2\u3001\u6559\u5b66\u6cd5\u4e0e\u5a31\u4e50\u8ba1\u7b97\u7814\u7a76\u7ec4\u8d1f\u8d23\u4eba\", \"unit_zh\": \"\u7ef4\u4e5f\u7eb3\u5927\u5b66\u8ba1\u7b97\u673a\u79d1\u5b66\u5b66\u9662\", \"email_hook_zh\": \"\u60a8\u5c06 VR \u4e0e 2D \u5f62\u5f0f\u8fdb\u884c\u968f\u673a\u5bf9\u7167\u6bd4\u8f83\u7684\u7814\u7a76\uff0c\u6b63\u662f\u6211\u68c0\u9a8c\u624b\u52bf\u4e0e\u5149\u9057\u4ea7\u4f53\u9a8c\u76f8\u5bf9\u9759\u6001\u5c55\u793a\u6548\u679c\u6240\u9700\u7684\u5b9e\u9a8c\u6a21\u578b\u3002\", \"csc_status_zh\": \"\u672a\u77e5\"}, {\"name\": \"Hubert Mara\", \"school_en\": \"Freie Universit\u00e4t Berlin\", \"school_zh\": \"\u67cf\u6797\u81ea\u7531\u5927\u5b66\", \"country\": \"\", \"title\": \"Professor of Archaeoinformatics (Arch\u00e4oinformatik)\", \"unit\": \"Institute of Computational Ancient Studies, Department of History and Cultural Studies, Freie Universit\u00e4t Berlin\", \"homepage\": \"https://www.geschkult.fu-berlin.de/e/compas/mitarbeiter_innen/professuren/mara/index.html\", \"email\": \"hubert.mara@fu-berlin.de\", \"relevance\": 6, \"claim\": \"Mara \u662f\u67cf\u6797\u81ea\u7531\u5927\u5b66\u8003\u53e4\u4fe1\u606f\u5b66\u6559\u6388\uff0c\u4e13\u505a\u535a\u7269\u9986\u4e0e\u53d1\u6398\u73b0\u573a\u6587\u7269\u7684 2D/3D \u8ba1\u7b97\u5206\u6790\uff08GigaMesh\u3001\u6954\u5f62\u6587\u5b57 3D \u8bc6\u522b\uff09\uff0c\u662f FU \u4e2d\u4e0e\u7528\u6237'\u628a\u6587\u7269\u91cd\u5efa\u4e3a 3D/\u70b9\u4e91\u518d\u4ea4\u4e92'\u6700\u5bf9\u53e3\u7684\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://www.geschkult.fu-berlin.de/e/compas/mitarbeiter_innen/professuren/mara/index.html\", \"evidence_papers\": [{\"title\": \"Wedge Detection for Predictive Graphical Annotation of Cuneiform Tablets in 3D\", \"year\": 2024, \"venue\": \"Eurographics Workshop on Graphics and Cultural Heritage (GCH)\", \"url\": \"https://doi.org/10.2312/gch.20241260\", \"link_to_user\": \"\u6587\u7269 3D \u7279\u5f81\u68c0\u6d4b\u4e0e\u6807\u6ce8 \u2192 \u9752\u94dc\u5668\u7eb9\u9970/\u94ed\u6587\u7684\u4ea4\u4e92\u5f0f\u63ed\u793a\", \"title_zh\": \"\u7528\u4e8e\u4e09\u7ef4\u6954\u5f62\u6587\u5b57\u6ce5\u677f\u9884\u6d4b\u6027\u56fe\u5f62\u6807\u6ce8\u7684\u6954\u5f62\u68c0\u6d4b\"}, {\"title\": \"The Mainz Cuneiform Benchmark Dataset Series: Sign Annotations of 3D Rendered Tablets\", \"year\": 2025, \"venue\": \"Journal of Open Archaeology Data\", \"url\": \"https://doi.org/10.5334/joad.172\", \"link_to_user\": \"3D \u6587\u7269\u6570\u636e\u96c6 \u2192 \u7528\u6237\u7c92\u5b50\u5316\u6587\u7269\u7684\u6570\u636e\u6765\u6e90\u4e0e\u89c4\u8303\", \"title_zh\": \"\u7f8e\u56e0\u8328\u6954\u5f62\u6587\u5b57\u57fa\u51c6\u6570\u636e\u96c6\u7cfb\u5217\uff1a\u4e09\u7ef4\u6e32\u67d3\u6ce5\u677f\u7684\u7b26\u53f7\u6807\u6ce8\"}, {\"title\": \"Gigamesh von Zeile 1 zur 3D\", \"year\": 2026, \"venue\": \"Melusina Press\", \"url\": \"https://doi.org/10.26298/1981-5722-gvz1\", \"link_to_user\": \"GigaMesh 3D \u6587\u7269\u5904\u7406\u8f6f\u4ef6 \u2192 \u4ece\u7f51\u683c\u5230\u70b9\u4e91/\u7c92\u5b50\u7684\u5904\u7406\u6d41\u7a0b\", \"title_zh\": \"GigaMesh\uff1a\u4ece\u7b2c\u4e00\u884c\u5230\u4e09\u7ef4\uff08Gigamesh von Zeile 1 zur 3D\uff09\"}], \"evidence_projects_funding\": \"\u5b98\u65b9\u9875\uff1a2024 \u8d77\u4efb FU \u8003\u53e4\u4fe1\u606f\u5b66\u6559\u6388\uff08\u62d2\u7edd\u5965\u683c\u65af\u5821 W3 \u9080\u8bf7\uff09\uff1b2025 \u8d77\u5fb7\u56fd\u8003\u53e4\u7814\u7a76\u9662\uff08DAI\uff09\u901a\u8baf\u9662\u58eb\uff1b\u66fe\u521b\u5efa\u6d77\u5fb7\u5821 Forensic Computational Geometry Laboratory\uff1bADA \u6570\u5b57\u4eba\u6587\u4e2d\u5fc3\u9875\uff1a\u4e0e NFDI4Objects \u5408\u4f5c\u5236\u5b9a 3D \u5143\u6570\u636e\u6807\u51c6\u3002\", \"fit_to_user\": \"\u7528\u6237\u5174\u8da3\u4e2d\u7684'3D \u6a21\u578b\u8868\u9762\u91c7\u6837\u3001\u70b9\u4e91'\u6b63\u662f Mara \u7684\u65b9\u6cd5\u6838\u5fc3\uff1b\u53ef\u628a\u9752\u94dc\u5668/\u6566\u714c\u9020\u50cf\u7684 3D \u626b\u63cf\u6570\u636e\u5904\u7406\u4e0e\u624b\u52bf\u4ea4\u4e92\u5c55\u793a\u7ed3\u5408\uff1bFU \u6709 CSC \u901a\u9053\uff08active\uff09\u3002\", \"counterargument_risk\": \"\u7814\u7a76\u504f\u8ba1\u7b97\u51e0\u4f55\u4e0e\u8003\u53e4\u6570\u636e\uff0c\u4e0d\u505a\u4ea4\u4e92\u8bbe\u8ba1\u6216\u89c2\u4f17\u7814\u7a76\uff1b\u5bf9\u4e2d\u56fd\u9752\u94dc\u5668/\u4f5b\u6559\u9020\u50cf\u4e0d\u719f\uff1b\u9700\u8f83\u5f3a\u7f16\u7a0b\u4e0e\u51e0\u4f55\u5904\u7406\u80fd\u529b\u3002\", \"email_hook\": \"Your 3D work on cuneiform tablets and GigaMesh is the rigorous version of what my particle-based bronzes and Dunhuang figures do informally: turning scanned surfaces into something people can explore.\", \"sources\": [\"https://www.geschkult.fu-berlin.de/e/compas/mitarbeiter_innen/professuren/mara/index.html\", \"https://www.ada.fu-berlin.de/dh-fu/Personen/Mara/index.html\", \"https://orcid.org/0000-0002-2004-4153\"], \"verified\": true, \"csc_note\": \"\u67cf\u6797\u81ea\u7531\u5927\u5b66 CSC \u7ebf status=active\uff08\u5177\u4f53\u540d\u989d/\u622a\u6b62\u4ee5 CSC \u5f53\u5e74\u516c\u544a\u4e3a\u51c6\uff09\u3002\", \"matched_keywords\": [\"3D digitisation\", \"point clouds / surface sampling\", \"digital cultural heritage\", \"museum objects\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"hubert.mara@fu-berlin.de\", \"subject\": \"PhD enquiry (CSC): 3D heritage data and gesture-based exploration\", \"body\": \"Dear Professor Mara,\\n\\nYour 3D work on cuneiform tablets, from wedge detection (Eurographics GCH 2024) to the Mainz benchmark datasets and GigaMesh, is the rigorous version of what my prototypes do informally: turning scanned surfaces into something people can explore. I direct a teaching and research office for digital intangible cultural heritage at Quanzhou Huaguang College, and I would like to apply for a PhD at Freie Universit\u00e4t Berlin under your supervision, funded by a China Scholarship Council (CSC) scholarship.\\n\\nSince November 2025 I have led that office, teaching 3D character design and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran 9 product series at OSRAM/LEDVANCE (~100 SKUs, ~US$8M sales), including light-distribution analysis for Abu Dhabi's Zayed airport project, and led user research at LEEDARSON for smart-lighting lines selling over US$30M. My office also gives me a team for heritage digitisation.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, with MediaPipe hand tracking in the browser, so visitors brush away the \\\"dust\\\" with a fingertip and hold their palms together to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to connect 3D heritage analysis with public interaction: sampling scanned artefacts into point and particle representations that preserve their analytical features (inscriptions, decoration, tool marks), and studying how gesture-based exploration helps visitors notice those features.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nThe CSC application requires a supervisor's acceptance letter, so I would be grateful to know whether you would consider this topic. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aGigaMesh/\u6954\u5f62\u6587\u5b57 3D \u5206\u6790 \u2194 \u7528\u6237\u7684\u70b9\u4e91/\u8868\u9762\u91c7\u6837\u5174\u8da3\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1aFU \u7684 CSC \u5f53\u5e74\u622a\u6b62\u4e0e\u63a5\u6536\u51fd\u8981\u6c42\uff1bMara \u662f\u5426\u63a5\u6536\u8bbe\u8ba1\u80cc\u666f\u535a\u58eb\uff08\u5176\u9662\u7cfb\u4e3a\u5386\u53f2\u4e0e\u6587\u5316\u7814\u7a76\u5b66\u90e8\uff0c\u5b66\u4f4d\u53ef\u80fd\u4e3a Dr. phil.\uff09\uff1b\u63d0\u6848\u9700\u5f3a\u8c03 3D \u6570\u636e\u5904\u7406\u90e8\u5206\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff08CSC\uff09\uff1a\u4e09\u7ef4\u9057\u4ea7\u6570\u636e\u4e0e\u57fa\u4e8e\u624b\u52bf\u7684\u63a2\u7d22\", \"body_zh\": \"\u5c0a\u656c\u7684 Mara \u6559\u6388\uff1a\\n\\n\u60a8\u5728\u6954\u5f62\u6587\u5b57\u6ce5\u677f\u65b9\u9762\u7684\u4e09\u7ef4\u7814\u7a76\uff0c\u4ece\u6954\u5f62\u7b14\u753b\u68c0\u6d4b\uff08Eurographics GCH 2024\uff09\u5230\u7f8e\u56e0\u8328\u57fa\u51c6\u6570\u636e\u96c6\u548c GigaMesh\uff0c\u662f\u6211\u7684\u539f\u578b\u4ee5\u975e\u6b63\u5f0f\u65b9\u5f0f\u6240\u505a\u4e4b\u4e8b\u7684\u4e25\u8c28\u7248\u672c\uff1a\u628a\u626b\u63cf\u5f97\u5230\u7684\u8868\u9762\u53d8\u6210\u4eba\u4eec\u53ef\u4ee5\u63a2\u7d22\u7684\u5bf9\u8c61\u3002\u6211\u5728\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u4e3b\u6301\u4e00\u4e2a\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u6559\u7814\u5ba4\uff0c\u5e0c\u671b\u5728\u60a8\u7684\u6307\u5bfc\u4e0b\u7533\u8bf7\u67cf\u6797\u81ea\u7531\u5927\u5b66\u7684\u535a\u58eb\uff0c\u8d44\u52a9\u6765\u6e90\u4e3a\u56fd\u5bb6\u7559\u5b66\u57fa\u91d1\u59d4\uff08CSC\uff09\u5956\u5b66\u91d1\u3002\\n\\n\u81ea2025\u5e7411\u6708\u8d77\uff0c\u6211\u4e3b\u6301\u8be5\u6559\u7814\u5ba4\uff0c\u4e3b\u8bb23D\u89d2\u8272\u8bbe\u8ba1\uff0c\u5e76\u4e3b\u6301VR\u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u4f5c\u4e3a\u7167\u660e\u884c\u4e1a\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff0c\u6211\u5728 OSRAM/LEDVANCE \u8d1f\u8d239\u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6100\u4e2aSKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6800\u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5e76\u5728\u7acb\u8fbe\u4fe1\uff08LEEDARSON\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc73000\u4e07\u7f8e\u5143\u3002\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u4e3a\u9057\u4ea7\u6570\u5b57\u5316\u63d0\u4f9b\u4e86\u56e2\u961f\u652f\u6301\u3002\\n\\n\u6211\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u7a9f\u663e\u50cf\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u6211\u5728 Three.js \u4e2d\u5c06\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u91cd\u5efa\u4e3aGPU\u7c92\u5b50\u4e91\uff0c\u5e76\u5728\u6d4f\u89c8\u5668\u4e2d\u4f7f\u7528 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u8ba9\u89c2\u4f17\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u57c3\u201d\uff0c\u518d\u53cc\u638c\u5408\u5341\uff0c\u663e\u73b0\u51fa\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u628a\u4e09\u7ef4\u9057\u4ea7\u5206\u6790\u4e0e\u516c\u4f17\u4ea4\u4e92\u8fde\u63a5\u8d77\u6765\uff1a\u5c06\u626b\u63cf\u6587\u7269\u91c7\u6837\u4e3a\u80fd\u591f\u4fdd\u7559\u5176\u5206\u6790\u7279\u5f81\uff08\u94ed\u6587\u3001\u7eb9\u9970\u3001\u5de5\u5177\u75d5\u8ff9\uff09\u7684\u70b9\u4e0e\u7c92\u5b50\u8868\u793a\uff0c\u5e76\u7814\u7a76\u57fa\u4e8e\u624b\u52bf\u7684\u63a2\u7d22\u5982\u4f55\u5e2e\u52a9\u89c2\u4f17\u6ce8\u610f\u5230\u8fd9\u4e9b\u7279\u5f81\u3002\\n\\n\u5766\u767d\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u662f\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u4f5c\u4e3a\u5408\u8457\u8005\u53d1\u8868\u8fc7\u4e24\u7bc7MR\u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5df2\u6388\u6743\u7684MR\u5b9a\u5236\u65b9\u6cd5\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\nCSC\u7533\u8bf7\u9700\u8981\u5bfc\u5e08\u7684\u63a5\u6536\u51fd\uff0c\u56e0\u6b64\u5982\u80fd\u5f97\u77e5\u60a8\u662f\u5426\u4f1a\u8003\u8651\u8fd9\u4e00\u8bfe\u9898\uff0c\u6211\u5c06\u4e0d\u80dc\u611f\u6fc0\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\uff0c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Jan Philipp Bullenkamp\", \"status\": \"current\", \"research_topic\": \"Semantic Segmentation of 3D Scanned Cultural Herita